<template>
  <scroll-view scroll-y class="page" :class="'bg-'+preview.cls"><view class="member-card" :class="preview.cls"><view><text class="ui-strong">{{ username }}</text><text class="ui-small">{{ preview.name }}</text></view><text>VIP</text><view class="metrics"><view><text class="ui-small">累积积分</text><text class="ui-strong">★ {{ totalPoints }}</text><text class="ui-small">{{ nextNeed ? `距下一等级还需 ${nextNeed} 积分` : '已达最高等级' }}</text></view><view><text class="ui-small">可用积分</text><text class="ui-strong">{{ points }}</text></view></view></view><view class="content"><text class="label">权益预览</text><scroll-view scroll-x class="pills" show-scrollbar="false"><view v-for="item in levels" :key="item.id" class="pill" :class="{ active: previewLevel===item.id }" @tap="previewLevel=item.id">{{ item.name }}</view></scroll-view><view v-if="previewLevel!==currentLevel" class="reset" @tap="previewLevel=currentLevel">回到我的等级</view><view class="table"><view class="row head"><text>权益项目</text><text v-for="level in levels" :key="level.id" :class="{ highlighted: previewLevel===level.id }">{{ level.name }}</text></view><view v-for="group in benefits" :key="group.category"><view class="category">{{ group.category }}</view><view v-for="item in group.items" :key="item.name" class="row"><text>{{ item.name }}</text><text v-for="level in levels" :key="level.id" :class="{ highlighted: previewLevel===level.id, yes: level.id>=item.minLevel }">{{ level.id>=item.minLevel ? '✓' : '–' }}</text></view></view></view></view></scroll-view>
</template>
<script>
import api from '../../common/api.js'
import auth from '../../common/auth.js'
const levels = [{id:1,name:'LV1',cls:'level-1',min:0},{id:2,name:'LV2',cls:'level-2',min:1200},{id:3,name:'LV3',cls:'level-3',min:3000},{id:4,name:'LV4',cls:'level-4',min:8000},{id:5,name:'LV5',cls:'level-5',min:20000},{id:6,name:'LV6',cls:'level-6',min:40000}]
const benefits = [{category:'基础身份',items:[{name:'SN全球唯一身份识别',minLevel:1},{name:'数字版《剪刀养护手册》',minLevel:1},{name:'会员专属数字化档案',minLevel:1}]},{category:'售后保障',items:[{name:'原厂1对1技术咨询',minLevel:1},{name:'出厂级二次精度校准',minLevel:1},{name:'原厂保养服务(积分)',minLevel:2},{name:'保养期【备用剪】申请',minLevel:4},{name:'保养绿色通道：3天内维保养完成',minLevel:5}]},{category:'物流特权',items:[{name:'标准物流包邮(首购)',minLevel:1},{name:'标准地区顺丰往返补贴',minLevel:1},{name:'全国地区顺丰往返补贴',minLevel:3}]},{category:'专属选购',items:[{name:'基础配件购买权',minLevel:1},{name:'专业级耗材积分换购',minLevel:2},{name:'限定版色彩/涂层选购',minLevel:3},{name:'新品内测/先行购买权',minLevel:5}]},{category:'高级定制',items:[{name:'SN码后四位专属连号',minLevel:5},{name:'主理人1对1调校建议',minLevel:6},{name:'专属黑金收藏级包装盒',minLevel:6}]}]
const levelFor = value => value>=40000?6:value>=20000?5:value>=8000?4:value>=3000?3:value>=1200?2:1
export default { data() { return { levels, benefits, currentLevel:1, previewLevel:1, points:0, totalPoints:0, username:'Sravx 用户' } }, computed: { preview() { return this.levels.find(item=>item.id===this.previewLevel)||this.levels[0] }, nextNeed() { const next=this.levels.find(item=>item.id===this.currentLevel+1); return next ? Math.max(0,next.min-this.totalPoints) : 0 } }, onLoad() { this.load() }, methods: { async load() { const saved=auth.user()||{}; let data=saved; try { if(saved.phone) data=await api.getUserInfo()||saved } catch(error) {} this.totalPoints=Number(data.total_points)||0; this.points=Number(data.points)||0; this.username=data.username||data.nickname||'Sravx 用户'; this.currentLevel=levelFor(this.totalPoints); this.previewLevel=this.currentLevel } } }
</script>
<style>
