tems:center;justify-content:center;flex:1;padding:9px 2px;color:#999;font-size:10px;text-align:center}.row>text:first-child{flex:2.4;padding-left:8px;justify-content:flex-start;color:#0B0D10;text-align:left}.row.head{background:rgba(0,0,0,.03)}.row.head text{font-size:9px}.category{padding:6px 8px;background:rgba(0,0,0,.02);color:#0B0D10;font-size:10px;font-weight:650}.row text.highlighted{background:rgba(29,29,31,.06)}.row text.yes{color:#4A4A4D;font-size:14px;font-weight:700}
</style>
